import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BZO4qERu.js";const C=JSON.parse('{"title":"Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/claude-code.md","filePath":"integrations/claude-code.md","lastUpdated":1781331939000}'),d={name:"integrations/claude-code.md"};function n(l,e,o,h,p,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><p>Claude Code 可以通过 <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a> 配置 Tokeness。CC Switch 用于管理 Claude Code、Codex、OpenCode 等工具的供应商配置，并支持在系统托盘切换。</p><h2 id="_1-准备环境" tabindex="-1">1. 准备环境 <a class="header-anchor" href="#_1-准备环境" aria-label="Permalink to &quot;1. 准备环境&quot;">​</a></h2><p>先确认三件事：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>Node.js</td><td>18 LTS 或更高版本</td></tr><tr><td>Claude Code</td><td>本机已经能安装并运行</td></tr><tr><td>Tokeness</td><td>已登录、已充值、已创建 API Key</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>安装 Claude Code：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><p>如果下载较慢，可临时使用镜像源：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry=https://registry.npmmirror.com</span></span></code></pre></div><h2 id="_2-安装-cc-switch" tabindex="-1">2. 安装 CC Switch <a class="header-anchor" href="#_2-安装-cc-switch" aria-label="Permalink to &quot;2. 安装 CC Switch&quot;">​</a></h2><p>按 CC Switch 官方安装页完成安装：<a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">https://ccswitch.io/zh/docs?section=getting-started</a></p><p>安装完成后启动 CC Switch，确认系统托盘里能看到图标。</p><h2 id="_3-添加-tokeness-供应商" tabindex="-1">3. 添加 Tokeness 供应商 <a class="header-anchor" href="#_3-添加-tokeness-供应商" aria-label="Permalink to &quot;3. 添加 Tokeness 供应商&quot;">​</a></h2><ol><li>在 CC Switch 左侧选择 Claude Code。</li><li>点击右上角 <code>+</code> 添加供应商。</li><li>如果预设里没有 Tokeness，选择“自定义”。</li><li>名称填写 <code>Tokeness</code>。</li><li>API Key 填写 Tokeness 控制台创建的 Key。</li><li>Base URL 填写 <code>https://n.tokeness.io/v1</code>。</li><li>模型填写 Tokeness 模型广场中的模型名。</li></ol><p>Tokeness 是 OpenAI 兼容接口。若 Claude Code 供应商表单提供 API 格式选项，选择 OpenAI Chat Completions 或 OpenAI Responses，并按 CC Switch 提示开启代理或应用接管。</p><h2 id="_4-切换并生效" tabindex="-1">4. 切换并生效 <a class="header-anchor" href="#_4-切换并生效" aria-label="Permalink to &quot;4. 切换并生效&quot;">​</a></h2><p>添加完成后，点击 Tokeness 供应商卡片上的“启用”。如果 Claude Code 没有读取新配置，关掉 Claude Code 再重新打开一次。</p><p>如果 Claude Code 首次启动时出现官方初始化引导，可以在 CC Switch 的“设置 → 通用”中开启“跳过 Claude Code 初次安装确认”，然后重新启动 Claude Code。</p><h2 id="_5-验证" tabindex="-1">5. 验证 <a class="header-anchor" href="#_5-验证" aria-label="Permalink to &quot;5. 验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><p>启动后输入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你好，请简单介绍一下自己</span></span></code></pre></div><p>如果能正常回复，再到 Tokeness “使用日志”中确认请求记录。</p>`,24)])])}const k=a(d,[["render",n]]);export{C as __pageData,k as default};
